using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 string mountedBlueprint;double vehicleSendClock;readonly Dictionary<string,double> vehicleDriveClock=new();readonly Dictionary<string,long> vehicleDrivers=new();
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopMount(string id){if(CoopClient){mountedBlueprint=id;CloseMenu();}}
 bool TickMounted(double dt){if(string.IsNullOrEmpty(mountedBlueprint))return false;var p=game.Building.Pieces.FirstOrDefault(p=>p.Id==mountedBlueprint);if(p==null||p.Health<=0||dungeon!=null){mountedBlueprint=null;return false;}if(paused)return false;
  vehicleSendClock-=dt;if(vehicleSendClock<=0){vehicleSendClock=.2;int turn=(Input.IsPhysicalKeyPressed(Key.D)?1:0)-(Input.IsPhysicalKeyPressed(Key.A)?1:0),throttle=(Input.IsPhysicalKeyPressed(Key.W)?1:0)-(Input.IsPhysicalKeyPressed(Key.S)?1:0);string data=p.Id+"|"+turn+"|"+throttle;if(!CoopRequest("drive",data))DriveBlueprint(data);}
  player.Position=new((float)p.X,(float)(p.Y+p.Def.H+.2),(float)p.Z);player.Velocity=Vector3.Zero;game.Save.X=p.X;game.Save.Z=p.Z;StreamTerrain();SpawnObjects();if(game.Tick(dt,false)&&!CoopClient)Die();TickBaseSystems(dt);if(!CoopClient)TickEnemies(dt);CoopTick(dt);saveClock+=dt;if(saveClock>=10){saveClock=0;game.Persist();}return true;
 }
 void Dismount(){string id=mountedBlueprint;if(id==null)return;if(!CoopRequest("dismount",id))vehicleDrivers.Remove(id);var p=game.Building.Pieces.FirstOrDefault(x=>x.Id==id);mountedBlueprint=null;if(p!=null){Vector3 candidate=Ground(p.X+p.Def.W/2+1,p.Z);if(OutdoorFree(candidate.X,candidate.Z))player.Position=candidate+Vector3.Up*.3f;}player.Velocity=Vector3.Zero;}
 void DriveBlueprint(string data){var args=data.Split('|');if(args.Length!=3||!int.TryParse(args[1],out int turn)||!int.TryParse(args[2],out int throttle)||Math.Abs(turn)>1||Math.Abs(throttle)>1)return;var p=game.Building.Pieces.FirstOrDefault(p=>p.Id==args[0]&&p.Def.Function is "mobile" or "vehicle");if(p==null||p.Health<=0||!vehicleDrivers.TryGetValue(p.Id,out long driver)||driver!=coopActor||ExpeditionGame.Distance(p.X,p.Z,player.Position.X,player.Position.Z)>5)return;if(vehicleDriveClock.TryGetValue(p.Id,out double previous)&&game.Clock-previous<.17)return;vehicleDriveClock[p.Id]=game.Clock;
  double yaw=p.Yaw+turn*10,x=p.X-Math.Sin(yaw*Math.PI/180)*throttle*(p.Def.Function=="vehicle"?1.3:.7),z=p.Z-Math.Cos(yaw*Math.PI/180)*throttle*(p.Def.Function=="vehicle"?1.3:.7);if(!game.World.Playable(x,z)||Math.Abs(game.World.Height(x,z)-p.Y)>.55)return;var proposal=new BuildPiece{Kind=p.Kind,X=x,Y=game.World.Height(x,z),Z=z,Yaw=yaw};var exclusions=new Godot.Collections.Array<Rid>{player.GetRid()};foreach(var node in buildRoot.GetChildren())if(node is Node3D n&&n.HasMeta("blueprint")&&n.GetMeta("blueprint").AsString()==p.Id)foreach(var child in n.FindChildren("*","StaticBody3D",true,false))if(child is StaticBody3D body)exclusions.Add(body.GetRid());var q=new PhysicsShapeQueryParameters3D{Shape=new BoxShape3D{Size=new((float)p.Def.W,.8f,(float)p.Def.D)},Transform=new(Basis.FromEuler(new(0,(float)(yaw*Math.PI/180),0)),new((float)x,(float)proposal.Y+.8f,(float)z)),Exclude=exclusions,Margin=.01f};foreach(var hit in GetWorld3D().DirectSpaceState.IntersectShape(q))if(hit["collider"].AsGodotObject() is Node node&&!node.IsInGroup("terrain"))return;
  p.X=x;p.Z=z;p.Y=proposal.Y;p.Yaw=yaw;player.Position=new((float)x,(float)(p.Y+p.Def.H+.2),(float)z);game.AwardResearch("milestone/driver",8);SyncStructures();if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));
 }
}
